package com.example.madfinalproject;

import android.content.Context;
import android.content.SharedPreferences;
import android.graphics.Color;
import android.graphics.Typeface;
import android.os.Bundle;
import android.view.Gravity;
import android.view.View;
import android.widget.Button;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.TextView;
import android.widget.Toast;
import androidx.appcompat.app.AppCompatActivity;
import org.json.JSONArray;
import org.json.JSONObject;
import java.util.ArrayList;
import java.util.List;

/** Grassroots cricket tournament companion. Match events are persisted locally for offline use. */
public class MainActivity extends AppCompatActivity {
    private static final int INK=Color.rgb(19,35,30), MUTED=Color.rgb(107,124,115), PAPER=Color.rgb(246,248,243), GREEN=Color.rgb(24,111,75), LIME=Color.rgb(197,235,91), WHITE=Color.WHITE, LINE=Color.rgb(225,232,222);
    private LinearLayout root, content, nav; private String page="Home", role="Organizer"; private Match match;
    @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(PAPER);getWindow().setNavigationBarColor(PAPER);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);match=new Match(this);show();}
    private int dp(float x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
    private void show(){
        root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(PAPER);setContentView(root);
        LinearLayout top=new LinearLayout(this);top.setPadding(dp(22),dp(12),dp(22),dp(10));top.setGravity(Gravity.CENTER_VERTICAL);top.setBackgroundColor(PAPER);
        TextView brand=label("BOUNDARY  /  CLUB CRICKET",11,GREEN,true);top.addView(brand,new LinearLayout.LayoutParams(0,dp(32),1));Button roleBtn=button(role+"  ▾",false);roleBtn.setOnClickListener(v->roles());top.addView(roleBtn);root.addView(top);
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);content=new LinearLayout(this);content.setOrientation(1);content.setPadding(dp(20),dp(8),dp(20),dp(24));scroll.addView(content);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        nav=new LinearLayout(this);nav.setPadding(dp(8),dp(8),dp(8),dp(8));nav.setBackgroundColor(WHITE);String[] tabs={"Home","Score","Tournaments","Insights"};for(String t:tabs){Button btt=button(t.equals(page)?t+"  •":t,t.equals(page));btt.setTextSize(11);btt.setPadding(dp(4),dp(9),dp(4),dp(9));btt.setOnClickListener(v->{page=t;show();});nav.addView(btt,new LinearLayout.LayoutParams(0,dp(44),1));}root.addView(nav);
        if(page.equals("Home"))home();else if(page.equals("Score"))score();else if(page.equals("Tournaments"))tournaments();else insights();
    }
    private TextView label(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextColor(color);t.setTextSize(size);if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
    private Button button(String s,boolean primary){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(13);b.setTypeface(null,Typeface.BOLD);b.setTextColor(primary?WHITE:INK);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(primary?GREEN:Color.rgb(238,242,235)));return b;}
    private void title(String eyebrow,String heading,String sub){TextView e=label(eyebrow.toUpperCase(),11,GREEN,true);e.setLetterSpacing(.08f);content.addView(e);TextView h=label(heading,30,INK,true);h.setPadding(0,dp(6),0,dp(4));content.addView(h);if(sub!=null){TextView s=label(sub,14,MUTED,false);s.setLineSpacing(dp(3),1);content.addView(s);}}
    private void gap(int h){View v=new View(this);content.addView(v,new LinearLayout.LayoutParams(1,dp(h)));}
    private void card(String eyebrow,String heading,String body,String action,Runnable click){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(dp(17),dp(15),dp(17),dp(15));c.setBackgroundColor(WHITE);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.bottomMargin=dp(11);content.addView(c,cp);c.addView(label(eyebrow.toUpperCase(),10,GREEN,true));TextView h=label(heading,18,INK,true);h.setPadding(0,dp(6),0,dp(3));c.addView(h);TextView b=label(body,13,MUTED,false);b.setLineSpacing(dp(3),1);c.addView(b);if(action!=null){Button bt=button(action,true);bt.setOnClickListener(v->click.run());LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,dp(46));bp.topMargin=dp(12);c.addView(bt,bp);}}
    private void home(){title("Tournament desk  ·  2026","Cricket, in control.","One place for your fixtures, live scoring and match-day decisions.");gap(18);card("Live now  ·  Turf 2","Riverside XI  128/4","vs  Northside CC     •     14.2 / 20 overs\nRohan 42*     Aman 2/21","OPEN LIVE SCORER",()->{page="Score";show();});card("Your tournament","Monsoon Cup","8 teams   ·   League + final\nNext fixture  ·  Today, 6:30 PM","VIEW FIXTURES",()->{page="Tournaments";show();});card("Match-day tools","Ready when the game is","Offline scoring saves to this phone. Match insights update from the current scorecard.","EXPLORE INSIGHTS",()->{page="Insights";show();});TextView note=label("LOCAL-FIRST  ·  SCORE EVEN WHEN THE SIGNAL DROPS",10,MUTED,true);note.setGravity(Gravity.CENTER);note.setPadding(0,dp(9),0,0);content.addView(note);}
    private void score(){title("Match centre  ·  Live","Riverside XI","Northside CC  •  20 overs  •  6 balls per over");gap(16);LinearLayout board=new LinearLayout(this);board.setOrientation(1);board.setPadding(dp(18),dp(18),dp(18),dp(16));board.setBackgroundColor(INK);content.addView(board);board.addView(label("RIVERSIDE XI",11,LIME,true));TextView total=label(match.runs()+" / "+match.wickets(),43,WHITE,true);total.setPadding(0,dp(4),0,0);board.addView(total);board.addView(label(match.overText()+" overs     •     CRR "+match.crr()+"     •     Target 161",13,Color.rgb(196,207,199),false));gap(13);card("At the crease","Rohan 42*  (31)    ·    Dev 18*  (14)","Bowling  ·  Aman 2/21 (3.2)\nThis device is the scoring source. Changes are saved locally.",null,null);TextView prompt=label("LOG THIS BALL",11,GREEN,true);content.addView(prompt);gap(5);
        String[][] rows={{"0","1","2","3"},{"4","6","WICKET","UNDO"},{"WIDE","NO BALL","BYE","LEG BYE"},{"PENALTY +1","RETIRED HURT","END OVER","INTERRUPTION"}};
        for(String[] row:rows){LinearLayout r=new LinearLayout(this);for(String x:row){Button b=button(x,x.equals("4")||x.equals("6")||x.equals("WICKET"));b.setTextSize(11);b.setPadding(dp(2),dp(4),dp(2),dp(4));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(49),1);p.setMargins(dp(3),dp(3),dp(3),dp(3));r.addView(b,p);b.setOnClickListener(v->scoreAction(x));}content.addView(r);}
        gap(13);card("Voice scorer","Hands-free scoring","Voice input can be enabled on this phone. Speaker isolation requires a verified on-device voice model; standard speech recognition cannot identify the authorized scorer reliably.","SET UP VOICE",()->voiceSetup());card("Official tools","Match rules & interruptions","Adjust balls per over, extras, bowler limits and revised overs. Target recalculation uses a local resource-table estimate.","MATCH SETTINGS",()->settings());
    }
    private void scoreAction(String x){try{switch(x){case "UNDO":match.undo();break;case "WICKET":match.add(0,"WICKET",true);break;case "WIDE":case "NO BALL":case "BYE":case "LEG BYE":match.add(1,x,false);break;case "PENALTY +1":match.add(1,"PENALTY",false);break;case "END OVER":match.endOver();break;case "INTERRUPTION":settings();return;case "RETIRED HURT":match.retired++;match.save();break;default:match.add(Integer.parseInt(x),"BAT",false);}show();}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();}}
    private void tournaments(){title("Competition manager","Tournaments","Fixtures, standings and team administration.");gap(16);card("Active  ·  8 teams","Monsoon Cup","League stage  ·  12 matches\nSemifinals → Final\n\n1  Riverside XI       P 3    Pts 6\n2  Northside CC      P 3    Pts 4\n3  Hillview Tigers   P 2    Pts 2\n\nNRR is calculated from completed innings; add full scorecards for accurate results.","CREATE TOURNAMENT",()->new android.app.AlertDialog.Builder(this).setTitle("Create tournament").setMessage("Tournament setup is ready to connect to a local database. Choose a format to continue.").setPositiveButton("League",(d,w)->Toast.makeText(this,"League selected",Toast.LENGTH_SHORT).show()).setNegativeButton("Knockout",(d,w)->Toast.makeText(this,"Knockout selected",Toast.LENGTH_SHORT).show()).show());card("Team registration","Squads & officials","Add players, managers, scorers and umpires to a competition.","MANAGE TEAMS",()->new android.app.AlertDialog.Builder(this).setTitle("Team registrations").setMessage("Register a squad and assign match officials.").setPositiveButton("Done",null).show());card("Spectator view","Public scoreboards","Live and past matches, fixtures and points tables are browsable without an account.",null,null);}
    private void insights(){title("Match intelligence","Read the game.","Scorecard-led tools for captains, scorers and spectators.");gap(16);card("Live estimate  ·  heuristic","Riverside XI  64%","Northside CC  36%\nBased on runs, wickets, balls remaining and target. Informational estimate; not a trained predictive model.",null,null);card("Captain’s co-pilot","Attack the new batter’s off stump","A tactical prompt can use this match’s recorded scoring and dismissal patterns. No historical player database is connected yet.","FIELD PLACEMENT RADAR",()->groundMap());card("Automated commentary","14.2  ·  Four!","Rohan rocks back and finds the gap through cover. Riverside move to 128 for 4.","MATCH SUMMARY",()->new android.app.AlertDialog.Builder(this).setTitle("Match story").setMessage("Match summaries are generated from the recorded ball-by-ball events.").setPositiveButton("OK",null).show());card("Scorebook scanner","Import a paper scoresheet","Capture a scorebook photo and review extracted deliveries before importing.","OPEN SCANNER",()->scanner());card("Square-leg stump cam","Instant replay review","A rolling buffer needs camera capture and device testing before use in a match.","STUMP CAM SETUP",()->cameraSetup());card("Stadium PA","Bluetooth announcements","Speak boundaries, wickets and end-of-over scores through a connected speaker.","ANNOUNCER SETTINGS",()->voiceSetup());}
    private void groundMap(){new android.app.AlertDialog.Builder(this).setTitle("Field placement radar").setMessage("Suggested setup\n\n      3rd man       Fine leg\n\nPoint      •      Cover\n\n       Bowler   Mid-off\n\n      Mid-on       Square leg\n\n  Deep midwicket\n\nRecommendations are illustrative until player history is connected.").setPositiveButton("OK",null).show();}
    private void roles(){String[] rs={"Organizer","Manager","Scorer","Umpire","Captain","Player","Spectator"};new android.app.AlertDialog.Builder(this).setTitle("View as").setItems(rs,(d,w)->{role=rs[w];if(role.equals("Scorer")||role.equals("Umpire"))page="Score";show();}).show();}
    private void settings(){LinearLayout box=new LinearLayout(this);box.setPadding(dp(20),dp(10),dp(20),0);box.setOrientation(1);android.widget.EditText balls=field("Balls per over (4, 5, 6 or 8)","6"),pen=field("Wide / no-ball penalty", "1"), overs=field("Revised total overs", "16");box.addView(balls);box.addView(pen);box.addView(overs);new android.app.AlertDialog.Builder(this).setTitle("Match rules & interruption").setView(box).setPositiveButton("APPLY",(d,w)->{try{int bCount=Integer.parseInt(balls.getText().toString()),pCount=Integer.parseInt(pen.getText().toString()),revised=Integer.parseInt(overs.getText().toString());if((bCount!=4&&bCount!=5&&bCount!=6&&bCount!=8)||pCount<0||revised<1)throw new IllegalArgumentException();match.balls=bCount;match.penalty=pCount;match.save();Toast.makeText(this,"Rules saved offline · revised target estimate: "+(match.runs()+Math.max(1,(revised*match.balls-match.legal())/6)),Toast.LENGTH_LONG).show();show();}catch(Exception e){Toast.makeText(this,"Enter valid rule values",Toast.LENGTH_SHORT).show();}}).setNegativeButton("CANCEL",null).show();}
    private android.widget.EditText field(String hint,String val){android.widget.EditText e=new android.widget.EditText(this);e.setSingleLine(true);e.setHint(hint);e.setText(val);return e;}
    private void voiceSetup(){if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=android.content.pm.PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},41);return;}new android.app.AlertDialog.Builder(this).setTitle("Voice scorer setup").setMessage("Speak sample phrases in a quiet place. Android speech recognition can transcribe commands, but this build does not enroll a speaker identity or reject other voices. Confirm each recognized action before it is scored.").setPositiveButton("START LISTENING",(d,w)->listen()).setNegativeButton("CANCEL",null).show();}
    private void listen(){try{android.content.Intent i=new android.content.Intent(android.speech.RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(android.speech.RecognizerIntent.EXTRA_LANGUAGE_MODEL,android.speech.RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(android.speech.RecognizerIntent.EXTRA_PROMPT,"Say: four, six, wide, wicket, or undo last ball");startActivityForResult(i,42);}catch(Exception e){Toast.makeText(this,"Speech recognition is unavailable",Toast.LENGTH_SHORT).show();}}
    @Override protected void onActivityResult(int req,int res,android.content.Intent data){super.onActivityResult(req,res,data);if(req==42&&res==RESULT_OK&&data!=null){ArrayList<String> said=data.getStringArrayListExtra(android.speech.RecognizerIntent.EXTRA_RESULTS);if(said!=null&&!said.isEmpty()){String s=said.get(0).toLowerCase();new android.app.AlertDialog.Builder(this).setTitle("Confirm scorer command").setMessage("Recognized: “"+said.get(0)+"”\n\nSpeech recognition does not verify the speaker.").setPositiveButton("APPLY",(d,w)->{if(s.contains("undo"))scoreAction("UNDO");else if(s.contains("wicket")||s.contains("out"))scoreAction("WICKET");else if(s.contains("wide"))scoreAction("WIDE");else if(s.contains("six"))scoreAction("6");else if(s.contains("four"))scoreAction("4");else Toast.makeText(this,"Command not recognized",Toast.LENGTH_SHORT).show();}).setNegativeButton("CANCEL",null).show();}}}
    private void scanner(){if(checkSelfPermission(android.Manifest.permission.CAMERA)!=android.content.pm.PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.CAMERA},43);return;}new android.app.AlertDialog.Builder(this).setTitle("Paper scorebook scanner").setMessage("Camera permission is ready. OCR score extraction and delivery-by-delivery review require an OCR model, which is not bundled in this build.").setPositiveButton("OK",null).show();}
    private void cameraSetup(){if(checkSelfPermission(android.Manifest.permission.CAMERA)!=android.content.pm.PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.CAMERA},43);return;}new android.app.AlertDialog.Builder(this).setTitle("Stump cam").setMessage("Camera access granted. Continuous rolling capture and slow-motion replay need a tested CameraX recording pipeline; no video is being recorded in this prototype.").setPositiveButton("OK",null).show();}
    private static class Ball {int runs;String type;boolean wicket;Ball(int r,String t,boolean w){runs=r;type=t;wicket=w;}}
    private static class Match {final SharedPreferences pref;final List<Ball> events=new ArrayList<>();int balls=6,penalty=1,retired=0;Match(Context c){pref=c.getSharedPreferences("match_local",0);balls=pref.getInt("balls",6);penalty=pref.getInt("penalty",1);try{JSONArray a=new JSONArray(pref.getString("events","[]"));for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);events.add(new Ball(o.getInt("r"),o.getString("t"),o.getBoolean("w")));}}catch(Exception ignored){}}
        void add(int r,String type,boolean wicket){events.add(new Ball(r,type,wicket));save();}void undo(){if(!events.isEmpty()){events.remove(events.size()-1);save();}}void endOver(){add(0,"OVER",false);}void save(){try{JSONArray a=new JSONArray();for(Ball b:events){JSONObject o=new JSONObject();o.put("r",b.runs);o.put("t",b.type);o.put("w",b.wicket);a.put(o);}pref.edit().putString("events",a.toString()).putInt("balls",balls).putInt("penalty",penalty).apply();}catch(Exception ignored){}}
        int runs(){int x=128;for(Ball b:events)x+=b.runs+(b.type.equals("WIDE")||b.type.equals("NO BALL")?penalty-1:0);return x;}int wickets(){int x=4;for(Ball b:events)if(b.wicket)x++;return Math.min(x,10);}int legal(){int x=86;for(Ball b:events)if(!b.type.equals("WIDE")&&!b.type.equals("NO BALL")&&!b.type.equals("OVER"))x++;return x;}String overText(){return (legal()/balls)+"."+(legal()%balls);}double crr(){return legal()==0?0:10.7*runs()/(128.0*legal()/86.0);}}
}
